@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const grid=document.querySelector('#damageGrid');document.querySelector('#addDamage').onclick=()=>{const row=document.createElement('div');row.className='damage-row';row.innerHTML='<input name="damage_labels[]" placeholder="Type de dégradation"><div class="input-unit"><input type="number" name="damage_amounts[]" min="0" step="100" value="0"><b>FCFA</b></div><button type="button" class="remove-damage"><i class="fa-solid fa-trash"></i></button>';grid.append(row)};grid.addEventListener('click',e=>{const button=e.target.closest('.remove-damage');if(button)button.closest('.damage-row').remove()})});</script>@endpush
